package in.wynk.secret.manager.images;

import java.util.Base64;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import java.io.FileOutputStream;
import java.io.IOException;

public class Base64ImageExtractor {
    public static void main(String[] args) {
        // Sample input containing Base64 image data
        String inputText = """
            ["data:image/jpeg;base64,", "data:image/jpeg;base64,", "data:image/jpeg;base64,", "data:image/jpeg;base64,","]
            """;

        // Regular expression to match Base64 image data
        Pattern pattern = Pattern.compile("data:image/jpeg;base64,([A-Za-z0-9+/=]+)");
        Matcher matcher = pattern.matcher(inputText);

        int imageCount = 1;
        while (matcher.find()) {
            String base64Data = matcher.group(1);  // Extract Base64 content

            // Decode Base64 to byte array
            byte[] imageBytes = Base64.getDecoder().decode(base64Data);

            // Save as a JPEG file
            String fileName = "image" + imageCount + ".jpg";
            try (FileOutputStream fos = new FileOutputStream(fileName)) {
                fos.write(imageBytes);
                System.out.println("Saved: " + fileName);
            } catch (IOException e) {
                System.err.println("Error saving file: " + fileName);
                e.printStackTrace();
            }

            imageCount++;
        }

        System.out.println("Extraction complete! Total images: " + (imageCount - 1));
    }
}
